package com.vandorlabs.neoforge.appliances;
import com.mojang.serialization.MapCodec;import com.vandorlabs.neoforge.*;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.BlockHitResult;
/** Full cube appliance housing; all physical controls use one front-local coordinate system. */
public final class NativeApplianceBlock extends BaseEntityBlock {
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;private final boolean scanner;
 public NativeApplianceBlock(Properties properties,boolean scanner){super(properties);this.scanner=scanner;registerDefaultState(stateDefinition.any().setValue(FACING,Direction.NORTH));}
 public boolean scanner(){return scanner;}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(FACING);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,c.getHorizontalDirection().getOpposite());}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new NativeApplianceEntity(p,s);}@Override protected RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Override protected BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override protected BlockState mirror(BlockState s,Mirror m){return s.rotate(m.getRotation(s.getValue(FACING)));}
 private static double localX(BlockHitResult h,BlockPos p,Direction f){double x=h.getLocation().x-p.getX(),z=h.getLocation().z-p.getZ();return switch(f){case SOUTH->1-x;case EAST->z;case WEST->1-z;default->x;};}
 private static double localZ(BlockHitResult h,BlockPos p,Direction f){double x=h.getLocation().x-p.getX(),z=h.getLocation().z-p.getZ();return switch(f){case SOUTH->1-z;case EAST->1-x;case WEST->x;default->z;};}
 private InteractionResult interact(Player player,Level level,BlockPos pos,InteractionHand hand,BlockHitResult hit,ItemStack held){if(hand!=InteractionHand.MAIN_HAND||!(level.getBlockEntity(pos) instanceof NativeApplianceEntity t)||t.inert()||!NativeConfigurationAccess.canEditDialog(player,level,pos,hit.getDirection()))return InteractionResult.FAIL;if(held.is(VandorLabsBootstrap.CONFIGURIZER.get()))return NativeApplianceBindings.open(player,level,pos)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;var facing=t.getBlockState().getValue(FACING);double x=localX(hit,pos,facing),z=localZ(hit,pos,facing),y=hit.getLocation().y-pos.getY();if(hit.getDirection()==facing){if(x>=.5625&&x<=.9375&&y>=.5625&&y<=.9375)return level.isClientSide||player instanceof net.minecraft.server.level.ServerPlayer p&&t.interactChip(p,hand)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;if(x>=.15&&x<=.35&&y>=.65&&y<=.85){if(player instanceof net.minecraft.server.level.ServerPlayer p)t.activate(p);return InteractionResult.sidedSuccess(level.isClientSide);}}if(scanner&&hit.getDirection()==Direction.UP&&x>=.125&&x<=.875&&z>=.125&&z<=.875)return level.isClientSide||player instanceof net.minecraft.server.level.ServerPlayer p&&t.interactFrame(p,hand)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;if(held.isEmpty())return NativeApplianceBindings.open(player,level,pos)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;return InteractionResult.PASS;}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState s,Level l,BlockPos p,Player actor,InteractionHand hand,BlockHitResult h){var result=interact(actor,l,p,hand,h,stack);return result==InteractionResult.FAIL?ItemInteractionResult.FAIL:result.consumesAction()?ItemInteractionResult.sidedSuccess(l.isClientSide):ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player actor,BlockHitResult h){return interact(actor,l,p,InteractionHand.MAIN_HAND,h,actor.getMainHandItem());}
 @Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(s.getBlock()!=next.getBlock()&&!l.isClientSide&&!com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(l,p)&&!com.vandorlabs.neoforge.gear.NativeGearHolds.reserved(l,p)&&!com.vandorlabs.neoforge.transfer.NativeTransferHolds.reserved(l,p)&&l.getBlockEntity(p) instanceof NativeApplianceEntity t)for(var stack:t.ownedDrops())net.minecraft.world.Containers.dropItemStack(l,p.getX()+.5,p.getY()+.8,p.getZ()+.5,stack);super.onRemove(s,l,p,next,moving);}
 @Override protected java.util.List<ItemStack> getDrops(BlockState s,net.minecraft.world.level.storage.loot.LootParams.Builder b){if(b.getOptionalParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_ENTITY) instanceof NativeApplianceEntity t&&t.inert()){var recovery=new ItemStack(this);recovery.set(net.minecraft.core.component.DataComponents.BLOCK_ENTITY_DATA,net.minecraft.world.item.component.CustomData.of(t.saveWithFullMetadata(b.getLevel().registryAccess())));return java.util.List.of(recovery);}return super.getDrops(s,b);}
}
